// Runs the real pinned core. Input scene is generated by slam_visual_scene.py.
#include "VisualRecovery.h"
#include <rtabmap/core/CameraModel.h>
#include <rtabmap/core/Compression.h>
#include <cstring>
#include <rtabmap/core/LaserScan.h>
#include <rtabmap/core/Memory.h>
#include <rtabmap/core/Signature.h>
#include <rtabmap/utilite/ULogger.h>
#include <opencv2/imgcodecs.hpp>
#include <fstream>
#include <iostream>
#include <stdexcept>
#include <chrono>

int main(int argc, char **argv)
{
    if(argc != 4 && argc != 5) return 2;
    ULogger::setType(ULogger::kTypeConsole);
    ULogger::setLevel(ULogger::kWarning);
    const std::string root=argv[1], output=argv[2], mode=argv[3];
    const bool imuPrediction=mode=="imu_prediction";
    const bool regressedVisualCapture=mode=="vo_reacquire_regressed";
    const bool shortVisualLoss=mode=="vo_reacquire" || mode=="vo_reacquire_expired" || regressedVisualCapture;
    const bool voHandoff=mode=="vo_handoff" || mode=="vo_handoff_gap" || shortVisualLoss;
    const bool failedVisualSeed=mode=="first_visual_seed_failed";
    const bool firstVisualSeed=mode=="first_visual_seed" || failedVisualSeed;
    std::map<int,int> imageMask;
    if(mode=="scan_mask")
    {
        if(argc!=5) throw std::runtime_error("scan_mask needs the observed image-availability mask");
        std::ifstream mask(argv[4]); int frame,available;
        while(mask>>frame>>available) imageMask[frame]=available;
        if(imageMask.empty()) throw std::runtime_error("empty image-availability mask");
    }
    const bool delayedRgb=mode=="delayed_first_external_rgb";
    const bool delayedExternal=mode=="delayed_first_external" || delayedRgb;
    const bool rejectedColdQuery=mode=="rejected_cold_query";
    const bool neighborRetry=mode=="neighbor_retry";
    const bool continuityVisual=mode=="external_continuity_visual";
    const bool continuityOutage=mode=="external_continuity_outage" || mode=="external_continuity_outage_rgb" ||
        mode=="external_continuity_outage_new_run" || mode=="external_continuity_outage_stale";
    const bool externalContinuity=continuityOutage || mode=="external_continuity" || mode=="external_continuity_new_run" ||
        mode=="external_continuity_untagged" || mode=="external_continuity_stale";
    const bool stationaryAnchor=mode=="stationary_visual_anchor";
    const bool refreshAnchor=mode=="refresh_visual_anchor";
    const bool visualDuringChassisWait=mode=="vo_reacquire_chassis_wait";
    const bool staggeredChassisLoss=mode=="vo_reacquire_staggered_chassis";
    const bool visualAfterNeighborFailure=mode=="vo_reacquire_neighbor_retry";
    const bool externalDuringVisualLoss=mode=="vo_reacquire_unverified_external";
    const bool disagreeingNeighborRetry=mode=="vo_reacquire_disagreeing_neighbor";
    const bool crossedRecovery=visualDuringChassisWait || staggeredChassisLoss || visualAfterNeighborFailure ||
        externalDuringVisualLoss || disagreeingNeighborRetry;
    const int reacquisitionFrame=externalDuringVisualLoss || disagreeingNeighborRetry?5:4;
    const bool nativeRecovery=mode=="recovery" || mode=="recovery_gap" || mode=="recovery_event" ||
        mode=="scan_mask" || imuPrediction || voHandoff || firstVisualSeed || mode=="finalize_cache" || mode=="history_without_cache" || mode=="fallback_cov" || mode=="fallback_lost" ||
        mode=="fallback_unpaired" || mode=="resume" || mode=="rgb" || mode=="ltm" ||
        rejectedColdQuery || delayedExternal || neighborRetry || externalContinuity || continuityVisual || stationaryAnchor || refreshAnchor || crossedRecovery;
    rtabmap::ParametersMap p;
    // The same core parameters as mapping_parameters(); do not tune matching thresholds.
    p["Reg/Strategy"]="1"; p["Icp/Strategy"]="0"; p["Optimizer/Strategy"]="0";
    p["Icp/VoxelSize"]="0.04"; p["Grid/Sensor"]="0"; p["Grid/3D"]="true";
    p["Grid/CellSize"]="0.04"; p["RGBD/ProximityBySpace"]="true";
    p["RGBD/NeighborLinkRefining"]="true"; p["RGBD/ProximityOdomGuess"]="true";
    p["RGBD/ProximityPathMaxNeighbors"]="1"; p["Kp/MaxFeatures"]="500";
    p["Mem/BadSignaturesIgnored"]="false"; p["Grid/RangeMax"]="0";
    p["Rtabmap/MemoryThr"]=mode=="ltm"?"20":"300"; p["Rtabmap/TimeThr"]="3000";
    if(nativeRecovery)
    {
        p["RGBD/NeighborLinkRefining"]="false"; p["RGBD/LoopCovLimited"]="true";
        p["RGBD/ProximityOdomGuess"]="false"; // The RGB session's production configuration.
    }
    rtabmap::Rtabmap map; map.init(p, output+".db");
    const auto restoredNodes=map.getLocalOptimizedPoses().size();
    if((mode=="resume" || rejectedColdQuery) && restoredNodes==0)
        throw std::runtime_error("cold recovery regression requires an existing optimized map");
    const auto originalPoses=map.getLocalOptimizedPoses();
    rtabmap::Transform historyExternal;
    if(mode=="history_without_cache")
    {
        const auto *last=map.getMemory()->getLastWorkingSignature();
        if(!last || restoredNodes==0) throw std::runtime_error("missing historical map fixture");
        historyExternal=last->getPose();
        map.setOptimizedPoses({},{}); // Native LTM cold loading can reject the optimized cache.
    }
    motus::VisualRecovery recovery(p);
    std::ifstream manifest(root+"/frames.txt");
    if(!manifest) throw std::runtime_error("missing scene manifest");
    std::ofstream evidence(output+".jsonl");
    int i, hasPose; float externalX, truthX; std::string phase;
    bool gapInjected=false, resetGapInjected=false, bridgePending=false; int bridgeRelocalizations=0;
    cv::Mat previousDepth; float previousTruthX=0, previousExternalX=0;
    int scanOnlyFrames=0, retainedScanClosures=0, overwrittenEvents=0;
    int handoffFrames=0;
    bool relocalizeBlack=false; int rgbGapFrames=0;
    bool postClosureLoss=false, postClosureReacquired=false;
    size_t postClosureNodes=0;
    const rtabmap::Transform handoffOrigin(7.f,-3.f,.5f,0.f,0.f,.35f);
    rtabmap::Transform lastHandoff;
    std::map<int,rtabmap::Transform> beforeVisualFailure;
    while(manifest >> i >> hasPose >> externalX >> truthX >> phase)
    {
        if(mode!="recovery" && mode!="recovery_gap" && mode!="recovery_event" && mode!="resume" && !hasPose) break;
        if(phase=="depth_gap") continue; // Source interruption: no metric observation.
        const int sourceFrame=stationaryAnchor?0:((refreshAnchor && i>=3) || (disagreeingNeighborRetry && i==4)?2:i);
        if(stationaryAnchor) externalX=truthX=0.f;
        if(refreshAnchor && i>=3) { externalX=previousExternalX; truthX=previousTruthX; }
        cv::Mat rgb=cv::imread(root+"/"+std::to_string(sourceFrame)+".jpg");
        cv::Mat depth=cv::imread(root+"/"+std::to_string(sourceFrame)+".png", cv::IMREAD_UNCHANGED);
        if(rgb.empty() || depth.empty()) throw std::runtime_error("missing scene frame");
        const bool recoveryScenario=mode=="recovery" || mode=="recovery_gap" || mode=="recovery_event";
        bool visualFault=false;
        if(recoveryScenario && phase=="relocalize" && !relocalizeBlack)
            visualFault=relocalizeBlack=true;
        if(recoveryScenario && phase=="rgb_gap" && ++rgbGapFrames==3)
            visualFault=true; // The first two missing images preserve the VO gauge.
        const bool loseAfterClosure=mode=="recovery" && !postClosureLoss && phase=="relocalize" &&
            recovery.state()==motus::VisualRecovery::Localized && recovery.relocalizations()==1;
        if(loseAfterClosure) visualFault=true;
        if(visualFault) rgb.setTo(cv::Scalar::all(0));
        if(voHandoff)
        {
            if(i>=3) hasPose=0;
            if(i==7 && !shortVisualLoss) hasPose=1; // A numerical external input cannot revive an old VO pairing.
            if(i==6 || (i==7 && !shortVisualLoss)) rgb.setTo(cv::Scalar::all(0));
        }
        if(firstVisualSeed && i>0) hasPose=0;
        if(failedVisualSeed && i==0) rgb.setTo(cv::Scalar::all(0));
        const bool crossedLoss=crossedRecovery && i>=3 && i<reacquisitionFrame;
        if(crossedLoss) rgb.setTo(cv::Scalar::all(0));
        const bool outage=continuityOutage && i==1;
        if(outage && mode=="external_continuity_outage_rgb") rgb.setTo(cv::Scalar::all(0));
        const bool unpaired=mode=="fallback_unpaired" && i==1;
        if(unpaired) externalX-=200.f;
        const bool visualLost=mode=="fallback_lost" && i==2;
        if(visualLost)
        {
            rgb.setTo(cv::Scalar::all(0)); depth=previousDepth;
            truthX=previousTruthX; externalX=previousExternalX-200.f;
        }
        else if(mode=="fallback_lost" && i>2) externalX-=200.f;
        previousDepth=depth.clone(); previousTruthX=truthX; previousExternalX=externalX;
        const double f=260.;
        rtabmap::CameraModel camera(f,f,rgb.cols/2.,rgb.rows/2.,rtabmap::Transform::getIdentity(),0.,rgb.size());
        cv::Mat scan(1,depth.total(),CV_32FC3), projectedDepth(depth.size(),CV_32F); int count=0;
        for(int v=0;v<depth.rows;++v) for(int u=0;u<depth.cols;++u)
        {
            float z=depth.at<unsigned short>(v,u)/1000.f;
            projectedDepth.at<float>(v,u)=z;
            if(z>0) scan.at<cv::Vec3f>(0,count++)=cv::Vec3f((u-rgb.cols/2.f)*z/f,(v-rgb.rows/2.f)*z/f,z);
        }
        if(mode=="resume") depth=projectedDepth; // Production SensorData carries 32FC1 projected depth.
        if(rejectedColdQuery) rgb.setTo(cv::Scalar::all(0));
        const bool gap=mode=="recovery_gap" && phase=="external_reset" && !gapInjected;
        const bool resetGap=mode=="recovery_gap" && phase=="continuous_reset" && !resetGapInjected;
        const bool noImages=neighborRetry || (externalContinuity && !(outage && mode=="external_continuity_outage_rgb")) ||
            (stationaryAnchor && i==0) || (refreshAnchor && i>=1 && i<=3) ||
            (delayedExternal && !delayedRgb && i>=1) || mode=="no_rgb" || mode=="history_without_cache" ||
            (mode=="vo_handoff_gap" && i==3) ||
            (phase=="rgb_gap" && !visualFault) || phase=="external_rgb_gap" ||
            gap || resetGap || (mode=="fallback_cov" && i==1) ||
            (mode=="scan_mask" && !imageMask.at(i));
        // Processed scan cadence can be sparser than the measured chassis stream.
        const double skippedTime=externalContinuity && i>0?(mode=="external_continuity_stale"?5.1:2.1):0.;
        const double outageTime=continuityOutage?(i==2 && mode=="external_continuity_outage_stale"?4.:0.):skippedTime;
        const double stamp=crossedRecovery?1.+i*.5:regressedVisualCapture && i==7?6.5:
            i+1.+outageTime+(mode=="vo_reacquire_expired" && i>=7?2.:0.)+
            (mode=="fallback_lost" && i==3?.5:0.); // F2M can track after the old map alignment expires.
        rtabmap::SensorData data(noImages?cv::Mat():rgb,noImages?cv::Mat():depth,camera,0,stamp);
        if(externalContinuity && i>0)
            for(int j=0;j<count;++j) scan.at<cv::Vec3f>(0,j)[0]+=20.f; // No scan overlap with the anchor.
        data.setLaserScan(rtabmap::LaserScan(scan.colRange(0,count),0,0.f,rtabmap::LaserScan::kXYZ));
        auto ext=hasPose?rtabmap::Transform(externalX,0,0,0,0,0):rtabmap::Transform();
        if(neighborRetry && (i==1 || i==2))
            ext=rtabmap::Transform(externalX+200.f,0,0,0,0,0);
        if(externalContinuity || continuityVisual)
        {
            if(!outage && (i!=1 || mode!="external_continuity_untagged"))
            {
                const bool changed=(i==1 && mode=="external_continuity_new_run") ||
                    (i==2 && mode=="external_continuity_outage_new_run");
                cv::Mat payload(1,24,CV_8UC1,cv::Scalar::all(changed?2:1));
                std::memcpy(payload.data,"MOTUSOD1",8);
                data.setUserData(rtabmap::compressData2(payload),true);
            }
            if(outage) ext.setNull();
            else if(i==2 && !continuityOutage)
                ext=continuityVisual?map.getMemory()->getLastWorkingSignature()->getPose():
                    rtabmap::Transform(externalX+200.f,0,0,0,0,0);
        }
        if((voHandoff || firstVisualSeed) && hasPose) ext=handoffOrigin*ext;
        if(mode=="history_without_cache") ext=historyExternal;
        if(rejectedColdQuery || (delayedExternal && i<2)) ext.setNull();
        if(imuPrediction && (i==0 || i==2 || i==3))
        {
            constexpr char tag[]="MOTUSIMU";
            cv::Mat hint(1,64,CV_8UC1);
            const double values[]={i==3?30.:static_cast<double>(truthX)+.035,0.,0.,0.,0.,0.,1.};
            std::memcpy(hint.data,tag,8);
            std::memcpy(hint.data+8,values,sizeof(values));
            data.setUserData(rtabmap::compressData2(hint),true);
            ext.setNull();
        }
        if((visualDuringChassisWait && i<3) || (staggeredChassisLoss && i<=3))
        {
            cv::Mat payload(1,24,CV_8UC1,cv::Scalar::all(1));
            std::memcpy(payload.data,"MOTUSOD1",8);
            data.setUserData(rtabmap::compressData2(payload),true);
        }
        if(crossedRecovery && i>=3 && !(staggeredChassisLoss && crossedLoss))
        {
            if((visualAfterNeighborFailure && i<=reacquisitionFrame) || (externalDuringVisualLoss && i==4) ||
               (disagreeingNeighborRetry && i==3))
                ext=rtabmap::Transform(externalX+200.f,0,0,0,0,0);
            else ext.setNull();
        }
        if(disagreeingNeighborRetry && i==4)
        {
            const auto *anchor=map.getMemory()->getLastWorkingSignature();
            const auto displaced=rtabmap::Transform(0,.16f,0,0,0,0);
            ext=anchor->getPose()*displaced;
            const auto measured=rtabmap::RegistrationIcp(p).computeTransformation(anchor->sensorData(),data,displaced);
            if(measured.isNull() || (displaced.inverse()*measured).getNorm()<=.1)
                throw std::runtime_error("fixture must produce valid ICP that disagrees with the external pose");
        }
        const auto nodesBefore=map.getLocalOptimizedPoses().size();
        const int previousLocation=map.getLastLocationId();
        if(visualLost) beforeVisualFailure=map.getLocalOptimizedPoses();
        auto started=std::chrono::steady_clock::now();
        bool accepted=nativeRecovery?
            recovery.process(map,data,ext,cv::Mat::eye(6,6,CV_64F)*
                (mode=="resume"?1.:(externalContinuity || continuityVisual)?.0001:.01)):
            map.process(data,ext,cv::Mat::eye(6,6,CV_64F)*.01);
        double elapsed=std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-started).count();
        if(mode=="recovery_event" && recovery.state()==motus::VisualRecovery::Localized)
        {
            // Fault injection into the publication view only: the graph/geometry are unchanged.
            auto &published=const_cast<rtabmap::Statistics &>(map.getStatistics());
            published.setLoopClosureId(0);
            published.addStatistic(rtabmap::Statistics::kLoopVisual_inliers(),0.f);
            ++overwrittenEvents;
        }
        const auto &s=map.getStatistics(); auto pose=map.getLastLocalizationPose();
        if(nativeRecovery && (data.laserScanRaw().size()!=count ||
           cv::norm(data.laserScanRaw().data(),scan.colRange(0,count),cv::NORM_INF)!=0))
            throw std::runtime_error("visual odometry must preserve the original scan for native mapping");
        if(nativeRecovery && recovery.visualInliers()>=20 &&
           (data.keypoints().empty() || data.descriptors().rows!=static_cast<int>(data.keypoints().size())))
            throw std::runtime_error("visual odometry features must remain on the native map observation");
        auto stat=[&](const std::string &key) {auto j=s.data().find(key);return j==s.data().end()?0.f:j->second;};
        evidence << "{\"frame\":"<<i<<",\"phase\":\""<<phase<<"\",\"accepted\":"<<accepted
                 <<",\"ref\":"<<s.refImageId()<<",\"loop\":"<<s.loopClosureId()<<",\"proximity\":"<<s.proximityDetectionId()
                 <<",\"truth_x\":"<<truthX<<",\"x\":"<<(pose.isNull()?9999:pose.x())
                 <<",\"state\":"<<recovery.state()<<",\"odom_null\":"<<recovery.odom().isNull()<<",\"relocations\":"<<recovery.relocalizations()
                 <<",\"recovery_node\":"<<recovery.recoveryNode()<<",\"recovery_anchor\":"<<recovery.recoveryAnchor()
                 <<",\"recovery_inliers\":"<<recovery.recoveryInliers()
                 <<",\"visual_reacquired_inliers\":"<<stat("Motus/VisualReacquiredInliers/")
                 <<",\"measured_external_continuity\":"<<stat("Motus/MeasuredExternalContinuity/")
                 <<",\"visual_inliers\":"<<recovery.visualInliers()<<",\"nodes\":"<<map.getLocalOptimizedPoses().size()
                 <<",\"visual_fault\":"<<(visualFault || crossedLoss)<<",\"images\":"<<!noImages
                 <<",\"hypothesis\":"<<stat(rtabmap::Statistics::kLoopHighest_hypothesis_id())
                 <<",\"hypothesis_value\":"<<stat(rtabmap::Statistics::kLoopHighest_hypothesis_value())
                 <<",\"rejected\":"<<stat(rtabmap::Statistics::kLoopRejectedHypothesis())
                 <<",\"loop_inliers\":"<<stat(rtabmap::Statistics::kLoopVisual_inliers())
                 <<",\"loop_matches\":"<<stat(rtabmap::Statistics::kLoopVisual_matches())
                 <<",\"generic_proximity\":"<<stat(rtabmap::Statistics::kProximitySpace_detections_added_visually())
                 <<",\"scan_proximity\":"<<stat(rtabmap::Statistics::kProximitySpace_detections_added_icp_multi())
                 <<",\"processing_ms\":"<<elapsed<<"}\n";
        evidence.flush();
        if(staggeredChassisLoss && crossedLoss)
        {
            const auto *signature=map.getMemory()->getLastWorkingSignature();
            if(!accepted || recovery.state()!=motus::VisualRecovery::External ||
               recovery.odom().isNull() || recovery.visualInliers()!=0 ||
               stat("Motus/MeasuredExternalContinuity/")!=1.f ||
               map.getLocalOptimizedPoses().size()!=nodesBefore+1 || !map.getMemory()->isIncremental() ||
               !signature || !signature->hasLink(previousLocation,rtabmap::Link::kNeighbor))
                throw std::runtime_error("the verified chassis must extend the active graph during visual loss");
        }
        if(crossedLoss && !staggeredChassisLoss && (accepted || recovery.state()!=motus::VisualRecovery::Searching ||
           !recovery.odom().isNull() || recovery.visualInliers()!=0 ||
           map.getLocalOptimizedPoses().size()!=nodesBefore || !map.getMemory()->isIncremental()))
            throw std::runtime_error("failed visual recovery must preserve the active graph without emitting a pose");
        if(crossedRecovery && i>=reacquisitionFrame)
        {
            const bool reacquiring=i==reacquisitionFrame;
            if(!accepted || recovery.state()!=motus::VisualRecovery::VisualTracking ||
               recovery.odom().isNull() || std::abs(recovery.odom().x()-(truthX+.024f))>.05f ||
               recovery.relocalizations()!=0 ||
               (reacquiring ? stat("Motus/VisualReacquiredInliers/")<20.f : stat("Motus/VisualReacquiredInliers/")!=0.f) ||
               stat("Motus/MeasuredExternalContinuity/")!=0.f ||
               map.getLocalOptimizedPoses().size()!=nodesBefore+1 || !map.getMemory()->isIncremental())
                throw std::runtime_error(mode+": recovery and following frame must extend the old graph with independently verified visual geometry");
            const auto *signature=map.getMemory()->getLastWorkingSignature();
            const auto link=std::find_if(signature->getLinks().begin(),signature->getLinks().end(),[](const auto & edge) {
                return edge.second.type()==rtabmap::Link::kNeighbor;
            });
            if(link==signature->getLinks().end() || link->second.transVariance()<.000399 ||
               link->second.rotVariance()<.000304 || !map.getLocalOptimizedPoses().count(1) ||
               (staggeredChassisLoss && !signature->hasLink(previousLocation,rtabmap::Link::kNeighbor)))
                throw std::runtime_error("recovered visual pose must preserve the graph anchor and carry visual motion uncertainty");
            if(!reacquiring) break;
        }
        if(refreshAnchor && i==3)
        {
            const auto *last=map.getMemory()->getLastWorkingSignature();
            if(!accepted || map.getLocalOptimizedPoses().size()!=3 || !last || last->id()!=3 || s.refImageId()!=4)
                throw std::runtime_error("the same-pose scan must be filtered before the next RGB-D anchor");
        }
        const int anchorFrame=refreshAnchor?4:1;
        const int anchorId=anchorFrame+1;
        const int neighborId=refreshAnchor?3:1;
        const size_t anchoredNodes=refreshAnchor?4:2;
        if((stationaryAnchor || refreshAnchor) && i==anchorFrame)
        {
            const auto *signature=map.getMemory()->getSignature(map.getLastLocationId());
            if(!accepted || recovery.odom().isNull() ||
               map.getLocalOptimizedPoses().size()!=anchoredNodes ||
               !signature || signature->getWords3().size()<20 || !signature->hasLink(neighborId,rtabmap::Link::kNeighbor))
                throw std::runtime_error("a measured stationary RGB-D observation must form a connected visual anchor after scan-only mapping");
        }
        if((stationaryAnchor || refreshAnchor) && i==anchorFrame+1)
        {
            if(map.getLocalOptimizedPoses().size()!=anchoredNodes)
                throw std::runtime_error("stationary frames must use regular keyframe gating after a visual anchor");
            map.close();
            rtabmap::Rtabmap reopened; reopened.init(p,output+".db");
            const auto *anchor=reopened.getMemory()->getSignature(anchorId);
            if(reopened.getLocalOptimizedPoses().size()!=anchoredNodes ||
               !anchor || anchor->getWords3().size()<20 || !anchor->hasLink(neighborId,rtabmap::Link::kNeighbor))
                throw std::runtime_error("the visual anchor must stay linked after reopening");
            reopened.close(false);
            return 0;
        }
        if(neighborRetry)
        {
            if(i==1 || i==2)
            {
                if(accepted || !recovery.odom().isNull() ||
                   recovery.state()!=motus::VisualRecovery::Searching ||
                   map.getLocalOptimizedPoses().size()!=nodesBefore)
                    throw std::runtime_error("a failed neighboring scan must neither publish odometry nor grow the map");
            }
            if(i==3)
            {
                if(!accepted || recovery.state()!=motus::VisualRecovery::External ||
                   recovery.odom().isNull() || map.getLocalOptimizedPoses().size()<=nodesBefore)
                    throw std::runtime_error("a verified neighboring scan must recover original map growth without RGB");
                map.close();
                return 0;
            }
        }
        if(externalContinuity && i>0)
        {
            if(outage)
            {
                if(accepted || !recovery.odom().isNull() || recovery.state()!=motus::VisualRecovery::Searching ||
                   map.getLocalOptimizedPoses().size()!=nodesBefore || !map.getMemory()->isIncremental())
                    throw std::runtime_error("chassis outage must wait without publishing a pose or modifying the map");
            }
            else if((i==1 && mode=="external_continuity") ||
                    (i==2 && (mode=="external_continuity_outage" || mode=="external_continuity_outage_rgb")))
            {
                const auto error=ext.inverse()*recovery.odom();
                if(!accepted || recovery.state()!=motus::VisualRecovery::External ||
                   error.isNull() || error.getNorm()>1e-6f || error.getAngle(rtabmap::Transform::getIdentity())>1e-6f ||
                   map.getLocalOptimizedPoses().size()!=nodesBefore+1)
                    throw std::runtime_error("verified measured external motion must grow the original graph through zero scan overlap");
                if(stat("Motus/MeasuredExternalContinuity/")!=1.f || !data.userDataCompressed().empty())
                    throw std::runtime_error("external continuity must be reported without persisting the internal run marker");
                const auto *signature=map.getMemory()->getLastWorkingSignature();
                const auto &links=signature->getLinks();
                if(links.size()!=1 || links.begin()->second.type()!=rtabmap::Link::kNeighbor ||
                   links.begin()->second.transVariance()<.002499 || links.begin()->second.rotVariance()<.00274 ||
                   !map.getLocalOptimizedPoses().count(1))
                    throw std::runtime_error("measured external continuity must preserve the anchor and encode only a conservative neighbor edge");
                if(continuityOutage) break;
            }
            else
            {
                if(accepted || recovery.state()!=motus::VisualRecovery::Searching ||
                   !recovery.odom().isNull() || map.getLocalOptimizedPoses().size()!=nodesBefore)
                    throw std::runtime_error("unverified external continuity must preserve the graph and publish no pose");
                break;
            }
        }
        if(continuityVisual && i==2)
        {
            const auto correction=ext.inverse()*recovery.odom();
            if(!accepted || recovery.state()!=motus::VisualRecovery::External || recovery.visualInliers()<20 ||
               stat("Motus/MeasuredExternalContinuity/")!=1.f || correction.isNull() || correction.x()<.10f ||
               map.getLocalOptimizedPoses().size()<=nodesBefore)
                throw std::runtime_error("a continuous chassis stream must retain independent visual correction");
            break;
        }
        if(visualFault && (recovery.visualInliers()>=20 ||
           recovery.state()!=motus::VisualRecovery::Searching || !recovery.odom().isNull() ||
           recovery.recoveryNode()!=0))
            throw std::runtime_error("decode-valid black image must exercise real VO loss before global recovery");
        if(loseAfterClosure)
        {
            if(accepted || !map.getMemory()->isIncremental() || map.getLocalOptimizedPoses().size()!=nodesBefore)
                throw std::runtime_error("short visual loss after closure must leave the old graph and mapping mode intact");
            postClosureLoss=true;
            postClosureNodes=nodesBefore;
        }
        else if(postClosureLoss && !postClosureReacquired)
        {
            if(!accepted || recovery.state()!=motus::VisualRecovery::VisualTracking || recovery.relocalizations()!=1 ||
               recovery.odom().isNull() || stat("Motus/VisualReacquiredInliers/")<20.f)
                throw std::runtime_error("a mapped visual landmark must support local restoration after global closure");
            postClosureReacquired=true;
        }
        if(mode=="recovery" && phase=="visual_only" && i==78 && (!postClosureReacquired ||
           map.getLocalOptimizedPoses().size()<postClosureNodes+3 || !map.getLocalOptimizedPoses().count(1)))
            throw std::runtime_error("reacquired visual tracking must continue growing the original graph");
        if(firstVisualSeed)
        {
            if(i==0 && (!accepted || recovery.state()!=motus::VisualRecovery::External ||
               recovery.visualInliers()!=0 || map.getLocalOptimizedPoses().size()!=1))
                throw std::runtime_error("first-frame handoff requires one measured map anchor before visual motion");
            if(i>0 && failedVisualSeed && (!recovery.odom().isNull() ||
               recovery.state()!=motus::VisualRecovery::Searching || map.getLocalOptimizedPoses().size()!=1))
                throw std::runtime_error("failed initial visual geometry cannot seed the map gauge");
            if(i>0 && !failedVisualSeed)
            {
                const auto local=handoffOrigin.inverse()*recovery.odom();
                if(!accepted || recovery.state()!=motus::VisualRecovery::VisualTracking || recovery.visualInliers()<20 ||
                   local.isNull() || std::abs(local.x()-truthX)>.05f || std::abs(local.y())>.05f ||
                   recovery.relocalizations()!=0 || map.getLocalOptimizedPoses().size()!=nodesBefore+1)
                    throw std::runtime_error("first measured RGB-D anchor must support later geometrically tracked visual-only growth");
            }
            if(i==2) break;
        }
        if(voHandoff)
        {
            if(mode=="vo_handoff_gap" && i==3)
            {
                if(accepted || recovery.state()!=motus::VisualRecovery::Searching ||
                   !recovery.odom().isNull() || map.getLocalOptimizedPoses().size()!=nodesBefore)
                    throw std::runtime_error("missing RGB at external loss must pause without losing the established gauge");
            }
            else if(i>=3 && i<=5)
            {
                const auto local=handoffOrigin.inverse()*recovery.odom();
                if(!accepted || recovery.state()!=motus::VisualRecovery::VisualTracking ||
                   recovery.visualInliers()<20 || recovery.odom().isNull() ||
                   recovery.relocalizations()!=0 || !map.getMemory()->isIncremental() ||
                   map.getLocalOptimizedPoses().size()<=nodesBefore ||
                   std::abs(local.x()-(truthX+.024f))>.05f || std::abs(local.y())>.05f ||
                   (!lastHandoff.isNull() && (lastHandoff.inverse()*recovery.odom()).getNorm()<.1f))
                    throw std::runtime_error("continuous measured VO must map across external pose loss in the established gauge");
                const auto &links=map.getMemory()->getLastWorkingSignature()->getLinks();
                const auto link=std::find_if(links.begin(),links.end(),[](const auto & edge) {
                    return edge.second.type()==rtabmap::Link::kNeighbor;
                });
                if(link==links.end() || link->second.transVariance()<.000399 ||
                   link->second.rotVariance()<.000304)
                    throw std::runtime_error("visual-only graph edges must retain conservative motion uncertainty");
                lastHandoff=recovery.odom(); ++handoffFrames;
            }
            if((i==6 || (i==7 && !shortVisualLoss)) && (recovery.visualInliers()!=0 || recovery.state()!=motus::VisualRecovery::Searching ||
               !recovery.odom().isNull() || recovery.recoveryNode()!=0))
                throw std::runtime_error("real visual failure must revoke continuous VO alignment");
            if(shortVisualLoss && i==6 && (map.getLocalOptimizedPoses().size()!=nodesBefore ||
               stat("Motus/VisualReacquiredInliers/")!=0.f))
                throw std::runtime_error("a failed visual frame must not move the graph");
            if(mode=="vo_reacquire" && i>=7)
            {
                const auto local=handoffOrigin.inverse()*recovery.odom();
                if(!accepted || recovery.state()!=motus::VisualRecovery::VisualTracking || local.isNull() ||
                   recovery.relocalizations()!=0 || map.getLocalOptimizedPoses().size()<=nodesBefore ||
                   !map.getLocalOptimizedPoses().count(1) || !map.getMemory()->isIncremental() ||
                   (i==7 && (std::abs(local.x()-(truthX+.024f))>.05f || std::abs(local.y())>.05f ||
                     stat("Motus/VisualReacquiredInliers/")<20.f)))
                    throw std::runtime_error("reacquired pre-loss F2M landmarks must extend the original graph");
            }
            if(regressedVisualCapture && i==7 && (accepted || !recovery.odom().isNull() ||
               recovery.state()!=motus::VisualRecovery::Searching || recovery.visualInliers()!=0 ||
               map.getLocalOptimizedPoses().size()!=nodesBefore))
                throw std::runtime_error("a capture older than the visual loss must not update VO or the map");
            if(regressedVisualCapture && i==8 && recovery.state()==motus::VisualRecovery::VisualTracking)
                throw std::runtime_error("timestamp regression must invalidate the pending visual alignment");
            if((i==8 && !shortVisualLoss) || (i==7 && mode=="vo_reacquire_expired"))
            {
                if(handoffFrames!=(mode=="vo_handoff_gap"?2:3) || recovery.state()==motus::VisualRecovery::VisualTracking)
                    throw std::runtime_error("old VO alignment must not bridge a real visual failure without global verification");
            }
            if(i==7 && mode=="vo_reacquire_expired") break;
        }
        if(imuPrediction)
        {
            if((i==0 || i==3) && (accepted || !recovery.odom().isNull() ||
               map.getLocalOptimizedPoses().size()!=nodesBefore))
                throw std::runtime_error("IMU guess seeded a map or bypassed scan validation");
            if(i==2 && (!accepted || recovery.state()!=4 || recovery.odom().isNull() ||
               std::abs(recovery.odom().x()-(truthX+.035f))<.005f ||
               map.getLocalOptimizedPoses().size()<=nodesBefore))
                throw std::runtime_error("verified inertial initial guess did not grow the old graph");
            if(i==3)
            {
                map.close(); return 0;
            }
        }
        if(delayedExternal)
        {
            if(i<2 && (!recovery.odom().isNull() || recovery.state()!=motus::VisualRecovery::Searching ||
                       !map.getLocalOptimizedPoses().empty()))
                throw std::runtime_error("an empty map without an external pose must await its first anchor");
            if(i==2 && (!accepted || recovery.state()!=motus::VisualRecovery::External ||
                       recovery.odom().isNull() || (ext.inverse()*recovery.odom()).getNorm()>1e-6f ||
                       ext.getAngle(recovery.odom())>1e-6f || map.getLocalOptimizedPoses().size()!=1 ||
                       !map.getMemory()->isIncremental() || recovery.relocalizations()!=0))
                throw std::runtime_error("first measured external pose must seed an empty map without RGB");
            if(i==3)
            {
                if(!accepted || map.getLocalOptimizedPoses().size()<=nodesBefore)
                    throw std::runtime_error("scan-only mapping must grow after a delayed first pose");
                const int rootId=map.getLocalOptimizedPoses().begin()->first;
                const int neighborId=map.getLastLocationId();
                map.close();
                if(delayedRgb)
                {
                    rtabmap::Rtabmap reopened; reopened.init(p,output+".db");
                    const auto *rootSignature=reopened.getMemory()->getSignature(rootId);
                    if(!reopened.getLocalOptimizedPoses().count(rootId) || !rootSignature ||
                       rootSignature->getWords().empty() || rootSignature->getWords3().empty() ||
                       !rootSignature->hasLink(neighborId,rtabmap::Link::kNeighbor))
                        throw std::runtime_error("first RGB-D anchor lacks persisted features or a connected neighbor");
                    auto saved=reopened.getMemory()->getNodeData(rootId,true,false,false,false);
                    if(saved.imageCompressed().empty() || saved.depthOrRightCompressed().empty())
                        throw std::runtime_error("first RGB-D anchor lacks saved color or depth");
                    reopened.close(false);
                }
                return 0;
            }
        }
        if(mode=="history_without_cache")
        {
            if(accepted || recovery.state()!=motus::VisualRecovery::Searching || !recovery.odom().isNull() ||
               !map.getLocalOptimizedPoses().empty())
                throw std::runtime_error("historical map without optimized cache must not trust a new external origin");
            map.close(false); return 0;
        }
        if(rejectedColdQuery)
        {
            if(!accepted || recovery.state()!=motus::VisualRecovery::Searching ||
               recovery.relocalizations()!=0 || !recovery.odom().isNull() ||
               map.getLocalOptimizedPoses()!=originalPoses)
                throw std::runtime_error("rejected cold query must retain the original optimized graph");
            if(i==2) break;
        }
        if(nativeRecovery)
        {
            if(mode=="resume" && i==0 && recovery.state()!=motus::VisualRecovery::Localized)
                throw std::runtime_error("unposed synchronous cold query did not recover on native visual geometry");
            if(recovery.state()==motus::VisualRecovery::Searching)
                for(const auto &link:s.odomCacheConstraints())
                    if(link.second.type()==rtabmap::Link::kNeighbor)
                        throw std::runtime_error("absent odometry must not create query motion constraints");
            if(recovery.state()==motus::VisualRecovery::Localized)
            {
                const auto *signature=map.getMemory()->getSignature(recovery.recoveryNode());
                if(recovery.recoveryNode()!=map.getLastLocationId() || recovery.recoveryAnchor()<=0 ||
                   recovery.recoveryInliers()<20 || !signature ||
                   !signature->hasLink(recovery.recoveryAnchor(),rtabmap::Link::kGlobalClosure))
                    throw std::runtime_error("recovery event lacks committed native global visual geometry");
                if(mode=="recovery_event" && (s.loopClosureId()!=0 || stat(rtabmap::Statistics::kLoopVisual_inliers())!=0))
                    throw std::runtime_error("publication statistics overwrite was not exercised");
            }
            else if(recovery.recoveryNode()!=0 || recovery.recoveryAnchor()!=0 || recovery.recoveryInliers()!=0)
                throw std::runtime_error("recovery event leaked into a later non-localized observation");
        }
        if(mode=="scan_mask" && noImages && accepted)
        {
            ++scanOnlyFrames;
            const auto *signature=map.getMemory()->getLastWorkingSignature();
            float factor=rtabmap::Parameters::defaultRGBDProximityMergedScanCovFactor();
            rtabmap::Parameters::parse(map.getParameters(),"RGBD/ProximityMergedScanCovFactor",factor);
            const auto &odomInfo=map.getMemory()->getOdomMaxInf();
            for(const auto &edge:signature->getLinks()) if(edge.second.type()==rtabmap::Link::kLocalSpaceClosure)
            {
                std::cout<<"scan-only type2 "<<signature->id()<<"->"<<edge.first<<" info="
                    <<edge.second.infMatrix().at<double>(0,0)<<" native_factor="<<factor<<std::endl;
                if(stat(rtabmap::Statistics::kProximitySpace_detections_added_icp_multi())>0)
                {
                    ++retainedScanClosures;
                    for(int axis=0;axis<6;++axis)
                        if(edge.second.infMatrix().at<double>(axis,axis)>odomInfo.at(axis)/factor*(1.+1e-6))
                            throw std::runtime_error("scan multi closure omitted the stock native covariance factor");
                }
            }
            if(stat(rtabmap::Statistics::kProximitySpace_detections_added_visually())>0)
                throw std::runtime_error("scan-only fallback entered the generic visual-proximity registration path");
        }
        if(gap || resetGap || visualLost || unpaired)
        {
            if(gap) gapInjected=true; else if(resetGap) resetGapInjected=true;
            bridgePending=true; bridgeRelocalizations=recovery.relocalizations();
            if(accepted || !recovery.odom().isNull() || recovery.state()!=motus::VisualRecovery::Searching ||
               map.getLocalOptimizedPoses().size()!=nodesBefore || !map.getMemory()->isIncremental())
                throw std::runtime_error("unverified external reset must not map or discard the existing graph");
            if(unpaired) {bridgePending=false; break;}
        }
        else if(bridgePending)
        {
            if(mode=="fallback_lost")
            {
                if(recovery.visualInliers()<20 || stat("Motus/VisualReacquiredInliers/")!=0.f ||
                   (recovery.state()!=motus::VisualRecovery::Searching &&
                    recovery.state()!=motus::VisualRecovery::Localized))
                    throw std::runtime_error("tracking after the verified alignment expires requires global verification before binding an external origin");
                if(recovery.state()==motus::VisualRecovery::Searching && !recovery.odom().isNull())
                    throw std::runtime_error("unverified recovery cannot emit a stale pose");
                if(recovery.state()==motus::VisualRecovery::Searching)
                {
                    std::map<int,rtabmap::Transform> preserved;
                    std::multimap<int,rtabmap::Link> preservedLinks;
                    map.getGraph(preserved,preservedLinks,true,true);
                    if(preserved.size()!=beforeVisualFailure.size() || beforeVisualFailure.empty() ||
                       !preserved.count(beforeVisualFailure.begin()->first) ||
                       (beforeVisualFailure.begin()->second.inverse()*
                        preserved.at(beforeVisualFailure.begin()->first)).getNorm()>1e-6f)
                        throw std::runtime_error("visual loss changed the old map origin or inserted an unverified external node");
                    for(const auto &pose:beforeVisualFailure)
                        if(!preserved.count(pose.first))
                            throw std::runtime_error("visual loss discarded an existing graph node");
                }
            }
            else if(!accepted || recovery.state()!=motus::VisualRecovery::External ||
                    recovery.relocalizations()!=bridgeRelocalizations)
                throw std::runtime_error("the next tracked RGB must bridge the new external origin without relocalizing");
            bridgePending=false;
        }
        if(mode=="fallback_cov" && i==1)
        {
            const auto &parameters=map.getParameters();
            const auto *signature=map.getMemory()->getLastWorkingSignature();
            if(!accepted || map.getLocalOptimizedPoses().size()<=nodesBefore || !signature)
                throw std::runtime_error("scan fallback with external odometry must keep mapping");
            const auto &link=signature->getLinks().begin()->second;
            std::cout << "fallback covariance=" << link.transVariance() <<
                " refining=" << parameters.at("RGBD/NeighborLinkRefining") <<
                " loopCovLimited=" << parameters.at("RGBD/LoopCovLimited") << std::endl;
            if(std::abs(signature->getPose().x()-externalX)>1e-6 ||
               std::abs(link.transVariance()-.01)>1e-8 ||
               parameters.at("RGBD/NeighborLinkRefining")!="false" ||
               parameters.at("RGBD/LoopCovLimited")!="true")
                throw std::runtime_error("optional RGB loss must preserve supplied neighbor covariance and loop weighting");
            break;
        }
        if(mode=="fallback_lost" && i==3) break;
        if(voHandoff && i==8) break;
    }
    if(mode=="recovery_event" && overwrittenEvents<2)
        throw std::runtime_error("native recovery event was not tested after publication statistics reset");
    if((mode=="recovery" || mode=="recovery_gap" || mode=="recovery_event") &&
       (!relocalizeBlack || rgbGapFrames!=3))
        throw std::runtime_error("two real visual failure observations were not exercised");
    if(mode=="recovery" && !postClosureReacquired)
        throw std::runtime_error("short visual loss after global recovery was not exercised");
    if(voHandoff && (handoffFrames!=(mode=="vo_handoff_gap"?2:3) || i!=(mode=="vo_reacquire_expired"?7:8)))
        throw std::runtime_error("continuous VO and real visual failure regression was not exercised");
    if(mode=="scan_mask" && (scanOnlyFrames<2 || retainedScanClosures==0))
        throw std::runtime_error("observed scan-only mask did not retain native ICP multi closures");
    if(mode=="fallback_unpaired" && i!=1)
        throw std::runtime_error("unpaired first visual registration/external origin regression was not exercised");
    if(mode=="fallback_lost" && (i!=3 || bridgePending))
        throw std::runtime_error("valid blank RGB/external origin recovery regression was not exercised");
    if(mode=="recovery_gap" && (!gapInjected || !resetGapInjected || bridgePending))
        throw std::runtime_error("missing RGB/external origin recovery regression was not exercised");
    if(mode=="resume" && (recovery.relocalizations()==0 ||
       map.getLocalOptimizedPoses().size()<restoredNodes+3 || recovery.state()!=motus::VisualRecovery::External))
        throw std::runtime_error("cold recovery did not continue mapping across the new external origin");
    const auto beforeFinalize=map.getLocalOptimizedPoses();
    std::map<int,rtabmap::Transform> complete;
    std::multimap<int,rtabmap::Link> completeLinks;
    map.getGraph(complete,completeLinks,false,true);
    if(mode=="ltm" && complete.size()<=beforeFinalize.size())
        throw std::runtime_error("LTM finalization regression did not evict graph nodes");
    motus::VisualRecovery::finalize(map);
    if(rejectedColdQuery && (i!=2 || map.getLocalOptimizedPoses()!=originalPoses))
        throw std::runtime_error("finalizing rejected cold queries changed the original graph");
    if(mode=="finalize_cache")
        for(const auto &pose:beforeFinalize)
            if(!map.getLocalOptimizedPoses().count(pose.first) ||
               (pose.second.inverse()*map.getLocalOptimizedPoses().at(pose.first)).getNorm()>1e-6f)
                throw std::runtime_error("finalization moved an already complete optimized map");
    if(mode=="ltm")
        for(const auto &pose:complete)
            if(!map.getLocalOptimizedPoses().count(pose.first))
                throw std::runtime_error("finalization omitted a connected LTM graph node");
    const auto finalized=map.getLocalOptimizedPoses();
    const auto lastLocation=map.getLastLocationId();
    map.exportPoses(output+"-optimized.txt",true,true,1);
    map.exportPoses(output+"-raw.txt",false,true,1);
    map.close();
    if(crossedRecovery)
    {
        rtabmap::Rtabmap reopened; reopened.init(p,output+".db");
        const auto *signature=reopened.getMemory()->getSignature(lastLocation);
        if(i!=reacquisitionFrame+1 || reopened.getLocalOptimizedPoses()!=finalized || finalized.size()!=(staggeredChassisLoss?6u:5u) ||
           !signature || !signature->hasLink(lastLocation-1,rtabmap::Link::kNeighbor))
            throw std::runtime_error("grown visual recovery graph must retain its nodes and links after reopening");
        reopened.close(false);
    }
    if(rejectedColdQuery)
    {
        rtabmap::Rtabmap reopened; reopened.init(p,output+".db");
        if(reopened.getLocalOptimizedPoses()!=originalPoses)
            throw std::runtime_error("reopening rejected cold queries changed the original graph");
        reopened.close(false);
    }
    if(mode=="finalize_cache")
    {
        rtabmap::Rtabmap reopened; reopened.init(p,output+".db");
        for(const auto &pose:finalized)
            if(!reopened.getLocalOptimizedPoses().count(pose.first) ||
               (pose.second.inverse()*reopened.getLocalOptimizedPoses().at(pose.first)).getNorm()>1e-6f)
                throw std::runtime_error("saved optimized cache changed on cold loading");
        reopened.close(false);
    }
}
